import ProductsList from '../../components/ProductsList';
import hiokisushi from '../../assets/pratos/Hioki Sushi/hiokisushi.png';
import diablo from '../../assets/images/diablo.png';
import zelda from '../../assets/images/zelda.png';
import starWars from '../../assets/images/star_wars.png';
import Pratos from '../../models/Pratos';

const promocoes: Pratos[] = [
  {
    id: 1,
    title: 'Hioki Sushi',
    nota: 4.5, // Alterado para number
    description:
      'Peça já o melhor da culinária japonesa no conforto da sua casa! Sushis frescos, sashimis deliciosos e pratos quentes irresistíveis. Entrega rápida, embalagens cuidadosas e qualidade garantida. Experimente o Japão sem sair do lar com nosso delivery!',
    image: hiokisushi,
    infos: ['15%', 'R$ 250,00'],
  },
  {
    id: 2,
    title: 'Diablo',
    nota: 4.0, // Alterado para number
    description:
      'Peça já o melhor da culinária japonesa no conforto da sua casa! Sushis frescos, sashimis deliciosos e pratos quentes irresistíveis. Entrega rápida, embalagens cuidadosas e qualidade garantida. Experimente o Japão sem sair do lar com nosso delivery!',
    image: diablo,
    infos: ['5%', 'R$ 290,00'],
  },
  // Adicione mais itens conforme necessário
];

const Categories = () => (
  <>
    <ProductsList pratos={promocoes} title="RPG" background="gray" />
    <ProductsList pratos={promocoes} title="Aventura" background="gray" />
  </>
);

export default Categories;
